const appBookingZones = `-- name: AppBookingZones :many

SELECT id, name, price_per_hour
FROM club_zones
WHERE club_id = $1
ORDER BY sort_order, id
`

type AppBookingZonesRow struct {
	ID           int64  `json:"id"`
	Name         string `json:"name"`
	PricePerHour *int64 `json:"price_per_hour"`
}

// Брони из гостевого приложения (тема Г, docs/upstream-2026-11.md; BR-174…BR-179, BR-190).
// Laravel: app/Services/GuestBookings.php, app/Services/ComputerReservations.php (startForSignedIn(), startByCode(),
// startPaidSession(), refund()), app/Http/Controllers/Api/GuestBookingController.php.
// Общие запросы броней — reservations.sql; блокировка тарифа и счётчик лимита — purchases.sql.
// ClubZone::query()->orderBy('sort_order')->orderBy('id')->get(['id', 'name', 'price_per_hour']).
func (q *Queries) AppBookingZones(ctx context.Context, clubID int64) ([]AppBookingZonesRow, error) {
	rows, err := q.db.Query(ctx, appBookingZones, clubID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AppBookingZonesRow
	for rows.Next() {
		var i AppBookingZonesRow
		if err := rows.Scan(&i.ID, &i.Name, &i.PricePerHour); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
